INSERT INTO wa_group ( tenant_id, group_jid, display_name, avatar_url, origin, created_at, updated_at, deleted_at ) SELECT #{tenantId}, incoming.group_jid, incoming.display_name, incoming.avatar_url, 5, incoming.created_at, incoming.updated_at, NULL FROM (
SELECT #{row.groupJid} AS group_jid, #{row.displayName} AS display_name, #{row.avatarUrl} AS avatar_url, #{row.now} AS created_at, #{row.now} AS updated_at
) incoming ORDER BY incoming.group_jid ASC ON DUPLICATE KEY UPDATE deleted_at = NULL, updated_at = GREATEST(updated_at, VALUES(updated_at))

