mapper.update:
UPDATE wa_group_participant SET presence_status = 2, presence_source = 'GROUP_SNAPSHOT', presence_observed_at = #{syncAt}, presence_event_id = #{eventId}, updated_at = GREATEST(updated_at, #{now}) WHERE id IN
#{participantId}
AND ( #{syncAt} > COALESCE(presence_observed_at, -1) OR ( #{syncAt} = presence_observed_at AND 1 > CASE presence_source WHEN 'WGP2_REMOVE' THEN 5 WHEN 'WGP2_LEAVE' THEN 5 WHEN 'REMOVE_EVENT' THEN 5 WHEN 'LEAVE_EVENT' THEN 5 WHEN 'UNKNOWN_EXIT_EVENT' THEN 5 WHEN 'WGP2_PROMOTE' THEN 4 WHEN 'WGP2_DEMOTE' THEN 4 WHEN 'WGP2_ADD' THEN 3 WHEN 'ADD_EVENT' THEN 3 WHEN 'GROUP_MEMBER_QUERY' THEN 2 WHEN 'FULL_SNAPSHOT' THEN 2 WHEN 'SNAPSHOT_ABSENT' THEN 2 WHEN 'GROUP_SNAPSHOT' THEN 1 ELSE 0 END ) )

mapper.insert:
INSERT INTO wa_account_group_binding ( tenant_id, account_id, group_id, participant_id, was_in_initial_baseline, baseline_subject_snapshot, membership_active_since_at, last_observed_at, first_post_control_observed_at, created_at, updated_at ) SELECT #{tenantId}, #{accountId}, incoming.group_id, participant.id, incoming.was_in_initial_baseline, incoming.baseline_subject_snapshot, incoming.membership_active_since_at, incoming.last_observed_at, incoming.first_post_control_observed_at, incoming.created_at, incoming.updated_at FROM (
SELECT #{row.groupId} AS group_id, #{row.pnJid} AS pn_jid, #{row.wasInInitialBaseline} AS was_in_initial_baseline, #{row.baselineSubjectSnapshot} AS baseline_subject_snapshot, #{row.membershipActiveSinceAt} AS membership_active_since_at, #{row.syncAt} AS last_observed_at, #{row.firstPostControlObservedAt} AS first_post_control_observed_at, #{row.now} AS created_at, #{row.now} AS updated_at
) incoming STRAIGHT_JOIN wa_group_participant participant FORCE INDEX (uq_wa_group_participant_pn) ON participant.tenant_id = #{tenantId} AND participant.group_id = incoming.group_id AND participant.pn_jid = incoming.pn_jid ORDER BY incoming.group_id ASC, incoming.pn_jid ASC ON DUPLICATE KEY UPDATE participant_id = VALUES(participant_id), was_in_initial_baseline = COALESCE( wa_account_group_binding.was_in_initial_baseline, VALUES(was_in_initial_baseline) ), baseline_subject_snapshot = COALESCE( wa_account_group_binding.baseline_subject_snapshot, VALUES(baseline_subject_snapshot) ), membership_active_since_at = CASE WHEN VALUES(membership_active_since_at) IS NOT NULL THEN VALUES(membership_active_since_at) ELSE wa_account_group_binding.membership_active_since_at END, last_observed_at = GREATEST( COALESCE(wa_account_group_binding.last_observed_at, VALUES(last_observed_at)), VALUES(last_observed_at) ), first_post_control_observed_at = COALESCE( wa_account_group_binding.first_post_control_observed_at, VALUES(first_post_control_observed_at) ), updated_at = GREATEST(wa_account_group_binding.updated_at, VALUES(updated_at))

INSERT INTO wa_account_group_binding (
  tenant_id, account_id, group_id, participant_id,
  was_in_initial_baseline, baseline_subject_snapshot,
  membership_active_since_at, last_observed_at,
  first_post_control_observed_at, created_at, updated_at
)
SELECT #{tenantId}, #{accountId}, #{row.groupId}, participant.id,
       CASE WHEN participant.presence_status = #{row.presenceStatus}
              AND participant.presence_source = #{row.presenceSource}
              AND participant.presence_observed_at = #{row.occurredAt}
            THEN #{row.wasInInitialBaseline} ELSE NULL END,
       CASE WHEN participant.presence_status = #{row.presenceStatus}
              AND participant.presence_source = #{row.presenceSource}
              AND participant.presence_observed_at = #{row.occurredAt}
            THEN #{row.baselineSubjectSnapshot} ELSE NULL END,
       CASE WHEN participant.presence_status = 1
              AND participant.presence_source = #{row.presenceSource}
              AND participant.presence_observed_at = #{row.occurredAt}
            THEN #{row.membershipActiveSinceAt} ELSE NULL END,
       #{row.occurredAt},
       CASE WHEN participant.presence_status = 1
              AND participant.presence_source = #{row.presenceSource}
              AND participant.presence_observed_at = #{row.occurredAt}
            THEN #{row.firstPostControlObservedAt} ELSE NULL END,
       #{row.now}, #{row.now}
FROM wa_group_participant participant FORCE INDEX (uq_wa_group_participant_pn)
WHERE participant.tenant_id = #{tenantId}
  AND participant.group_id = #{row.groupId}
  AND participant.pn_jid = #{row.pnJid}
ON DUPLICATE KEY UPDATE
  participant_id = VALUES(participant_id),
  was_in_initial_baseline = COALESCE(
    wa_account_group_binding.was_in_initial_baseline,
    VALUES(was_in_initial_baseline)
  ),
  baseline_subject_snapshot = COALESCE(
    wa_account_group_binding.baseline_subject_snapshot,
    VALUES(baseline_subject_snapshot)
  ),
  membership_active_since_at = COALESCE(
    VALUES(membership_active_since_at),
    wa_account_group_binding.membership_active_since_at
  ),
  last_observed_at = GREATEST(
    COALESCE(wa_account_group_binding.last_observed_at, VALUES(last_observed_at)),
    VALUES(last_observed_at)
  ),
  first_post_control_observed_at = COALESCE(
    wa_account_group_binding.first_post_control_observed_at,
    VALUES(first_post_control_observed_at)
  ),
  updated_at = GREATEST(wa_account_group_binding.updated_at, VALUES(updated_at))
